// GENERATED by the day-one font check (see FONTS.md): the Unicode code points present in both
// MonaSans-Bold.ttf and MonaSans-SemiBold.ttf (546 code points, identical in both weights).
// Regenerate with the fonttools script described in FONTS.md whenever the font files change.
//
// Readouts set in Mona Sans must only contain characters from this set; otherwise the whole
// readout switches to the platform face (with tabular figures) so symbol and digits share one
// face and one baseline. Single numbers are code points; pairs are inclusive ranges.

const RANGES: readonly (number | readonly [number, number])[] = [
  [0x0020, 0x007E], [0x00A0, 0x00AC], [0x00AE, 0x00B4], [0x00B6, 0x0137], [0x0139, 0x0148], [0x014A, 0x014D], [0x0150, 0x017E], 0x0192,
  [0x01A0, 0x01A1], [0x01AF, 0x01B0], [0x01E6, 0x01E7], [0x0218, 0x021B], 0x0237, [0x02C6, 0x02C7], [0x02D8, 0x02DD], [0x0300, 0x0304],
  [0x0306, 0x030C], 0x0312, 0x031B, 0x0323, [0x0326, 0x0328], [0x0335, 0x0338], 0x03BC, 0x03C0, 0x0E3F, [0x1E80, 0x1E85], 0x1E9E, [0x1EA0, 0x1EF9],
  [0x2013, 0x2014], [0x2018, 0x201A], [0x201C, 0x201E], 0x2022, 0x2026, 0x2030, [0x2039, 0x203A], 0x2044, 0x2070, [0x2074, 0x2079], [0x2080, 0x2089],
  [0x20A9, 0x20AA], 0x20AC, [0x20B8, 0x20BA], 0x20BF, 0x2113, [0x2116, 0x2117], 0x2122, 0x212E, [0x215B, 0x215E], [0x2190, 0x2194], 0x2205, 0x220F,
  [0x2211, 0x2212], 0x221A, 0x221E, 0x222B, 0x2248, 0x2260, [0x2264, 0x2265], [0x2460, 0x2468], 0x24EA, 0x24FF, [0x25CB, 0x25CC], 0x25CF,
  [0x2639, 0x263A], 0x2713, [0x2776, 0x277E], 0xF8FF, [0xFB01, 0xFB02],
];

const SINGLE = new Set<number>();
const SPANS: [number, number][] = [];
for (const r of RANGES) {
  if (typeof r === 'number') SINGLE.add(r);
  else SPANS.push([r[0], r[1]]);
}

/** True when Mona Sans has a glyph for this code point. */
export function monaSansHasCodePoint(codePoint: number): boolean {
  if (SINGLE.has(codePoint)) return true;
  for (const [start, end] of SPANS) if (codePoint >= start && codePoint <= end) return true;
  return false;
}

/** True when every character of the text has a glyph in Mona Sans. */
export function monaSansCovers(text: string): boolean {
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp !== undefined && !monaSansHasCodePoint(cp)) return false;
  }
  return true;
}
